import type { MarketplaceCategory } from '@/models/marketplace';

/**
 * The hrefs the marketplace screens push.
 *
 * They live next to the components that use them rather than in the model,
 * because they are navigation, not data. The object form is used instead of a
 * built-up string so the typed routes generated by Expo Router check the
 * pathname and the params together.
 */

export function categoryHref(category: MarketplaceCategory) {
  return {
    pathname: '/(marketplace)/category/[category]' as const,
    params: { category },
  };
}

export function productHref(id: string) {
  return {
    pathname: '/(marketplace)/product/[id]' as const,
    params: { id },
  };
}

/** Search across every listing, rather than inside one category. */
export function searchHref() {
  return '/(marketplace)/search' as const;
}

/** The farmer's saved listings. */
export function wishlistHref() {
  return '/(marketplace)/wishlist' as const;
}

/** The farmer's cart, with a quantity on each line. */
export function cartHref() {
  return '/(marketplace)/cart' as const;
}

/** 📦 Delivery details: the address form, the delivery speeds and the total. */
export function deliveryHref() {
  return '/(marketplace)/delivery' as const;
}

/**
 * ✅ The receipt for a placed order, named by its id so the View Order button
 * and a device back gesture both land on the same order.
 */
export function orderConfirmationHref(orderId: string) {
  return {
    pathname: '/(marketplace)/order-confirmation' as const,
    params: { id: orderId },
  };
}

/** One placed order, opened from the confirmation screen. */
export function orderHref(orderId: string) {
  return {
    pathname: '/(marketplace)/order/[id]' as const,
    params: { id: orderId },
  };
}

/**
 * 🌾 The Thank You, Farmer page.
 *
 * It lives at the top of the app, outside the `(marketplace)` group, because it
 * is a note from the team rather than anything to buy. The Marketplace reaches
 * it through this card.
 */
export function thankYouHref() {
  return '/thank-you' as const;
}
